// Runs on `npm install` (postinstall). Generated output is gitignored, not committed.
//
// Copies the built @openuidev/lang-core (MIT, Thesys Inc.) into shared/lang-core with its zod
// imports pointed at the root "zod" module. The Paseo app provides "zod" to plugin client code
// but not the "zod/v4" subpaths the published build imports, and its plugin compiler cannot
// bundle them either.
import { copyFile, mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = path.join(import.meta.dirname, "..");
const source = path.join(root, "node_modules", "@openuidev", "lang-core");
const dist = path.join(source, "dist");
const target = path.join(root, "shared", "lang-core");

const rewrites = [
  ['import { literal, object, z } from "zod/v4";', 'import { literal, object, z } from "zod";'],
  ['import * as z$1 from "zod/v4/core";', 'import { core as z$1 } from "zod";'],
  ['import { z } from "zod/v4";', 'import { z } from "zod";'],
];

await mkdir(target, { recursive: true });

for (const file of ["index.mjs", "index.d.mts"]) {
  let text = await readFile(path.join(dist, file), "utf8");
  text = text.replace(/\n?\/\/# sourceMappingURL=.*\s*$/, "\n");
  for (const [from, to] of rewrites) text = text.replace(from, to);
  if (/^import .* from "zod\/v4/m.test(text)) throw new Error(`${file} still imports a zod subpath`);
  await writeFile(path.join(target, file), text);
}
// Shared chunks (opt-in telemetry helpers), without their source map pointer.
for (const file of await readdir(dist)) {
  if (!/^shared-.*\.mjs$/.test(file)) continue;
  const text = await readFile(path.join(dist, file), "utf8");
  await writeFile(path.join(target, file), text.replace(/\n?\/\/# sourceMappingURL=.*\s*$/, "\n"));
}
await copyFile(path.join(source, "package.json"), path.join(target, "SOURCE-package.json"));

// The daemon evals the plugin bundle with no __dirname, so server code cannot find node_modules
// (needed to load the native rasterizer without bundling it) unless the path is written down here.
await writeFile(
  path.join(root, "server", "paths.generated.ts"),
  `// Generated by scripts/build.mjs on npm install. Do not edit or commit.\nexport const PLUGIN_DIR = ${JSON.stringify(root)};\n`,
);
console.log("Built shared/lang-core and server/paths.generated.ts");
